// Extract article links from Deadline
const data = $input.first().json;
const links = data.data?.links || [];
const markdown = data.data?.markdown || '';

const seen = new Set();
const articleLinks = [];

// Try structured links first
for (const link of links) {
  const url = typeof link === 'string' ? link : link.url;
  if (
    url &&
    url.includes('deadline.com') &&
    url.match(/deadline\.com\/\d{4}\//) &&
    !url.includes('/category/') &&
    !url.includes('/tag/') &&
    !url.includes('/author/') &&
    !seen.has(url)
  ) {
    seen.add(url);
    articleLinks.push(url);
  }
}

// Fallback: extract from markdown
if (articleLinks.length < 5) {
  const urlRegex = /https?:\/\/deadline\.com\/\d{4}\/\d{2}\/[^\s\)\]"]+/g;
  const matches = markdown.match(urlRegex) || [];
  for (const url of matches) {
    const clean = url.replace(/[\)\]".,]+$/, '');
    if (!seen.has(clean)) {
      seen.add(clean);
      articleLinks.push(clean);
    }
  }
}

// Return max 15 articles
return articleLinks.slice(0, 15).map(url => ({
  json: { url, source: 'Deadline' }
}));

// Extract article links from WorldofReel
const data = $input.first().json;
const links = data.data?.links || [];
const markdown = data.data?.markdown || '';

const seen = new Set();
const articleLinks = [];

// Try structured links first
for (const link of links) {
  const url = typeof link === 'string' ? link : link.url;
  if (
    url &&
    (url.includes('worldofreel.com') || url.includes('worldofreels.com')) &&
    !url.includes('images.squarespace') &&
    !url.includes('cdn.') &&
    !url.includes('.jpg') &&
    !url.includes('.jpeg') &&
    !url.includes('.png') &&
    !url.includes('format=') &&
    !url.includes('/category/') &&
    !url.includes('/tag/') &&
    !url.includes('/page/') &&
    url.split('/').length > 4 &&
    !seen.has(url)
  ) {
    seen.add(url);
    articleLinks.push(url);
  }
}

// Fallback: extract from markdown
if (articleLinks.length < 5) {
  const urlRegex = /https?:\/\/(?:www\.)?worldofreel[^\s\)\]"]+/g;
  const matches = markdown.match(urlRegex) || [];
  for (const rawUrl of matches) {
    const url = rawUrl.replace(/[\)\]".,]+$/, '');
    if (
      !url.includes('images.squarespace') &&
      !url.includes('.jpg') &&
      !url.includes('.jpeg') &&
      !url.includes('.png') &&
      !url.includes('format=') &&
      url.split('/').length > 4 &&
      !seen.has(url)
    ) {
      seen.add(url);
      articleLinks.push(url);
    }
  }
}

// Return max 15 articles
return articleLinks.slice(0, 15).map(url => ({
  json: { url, source: 'WorldofReel' }
}));

// Combine article URL + scraped content for Grok processing
const items = $input.all();
const results = [];

for (const item of items) {
  const markdown = item.json.data?.markdown || '';
  const url = item.json.data?.metadata?.url || item.json.data?.metadata?.sourceURL || '';
  const source = url.includes('deadline') ? 'Deadline' : 'WordofReels';

  if (markdown.length > 100) {
    results.push({
      json: {
        article_url: url,
        source: source,
        content: markdown.substring(0, 4000) // Limit content for API call
      }
    });
  }
}

return results;

// Deduplicate URLs before scraping
const items = $input.all();
const seen = new Set();
const unique = [];

for (const item of items) {
  const url = item.json.url;
  if (url && !seen.has(url)) {
    seen.add(url);
    unique.push(item);
  }
}

console.log(`Deduped: ${items.length} → ${unique.length} unique URLs`);
return unique;

const items = $input.all();
const keywords = [
  'producer', 'produced by', 'executive producer',
  'in production', 'greenlit', 'green lit',
  'set up at', 'in development', 'has been tapped',
  'will direct', 'is attached', 'acquired by',
  'film adaptation', 'feature film', 'is developing',
  'picked up', 'commissioned', 'announced today'
];

const filtered = items.filter(item => {
  const content = (item.json.content || '').toLowerCase();
  return keywords.some(kw => content.includes(kw));
});

console.log(`Filtered: ${items.length} → ${filtered.length} production articles`);
return filtered.length > 0 ? filtered : [{ json: { skip: true } }];

const items = $input.all();
const results = [];

for (const item of items) {
  try {
    const raw = item.json.output || '';
    const cleaned = raw.replace(/```json|```/g, '').trim();
    const parsed = JSON.parse(cleaned);

    // Skip if both are N/A
    if (parsed.producer === 'N/A' && parsed.title === 'N/A') continue;

    // Skip if producer is N/A (no point saving without a producer)
    if (parsed.producer === 'N/A') continue;

    // Split multiple producers into separate rows
    const producers = parsed.producer.split(',').map(p => p.trim()).filter(p => p && p !== 'N/A');

    for (const producer of producers) {
      results.push({
        json: {
          producer_name: producer,
          film_title: parsed.title || 'N/A',
          article_url: item.json.article_url || '',
          source: item.json.source || '',
          scraped_at: new Date().toISOString()
        }
      });
    }
  } catch(e) {
    console.log('Skipped unparseable item:', e.message);
  }
}

return results;

