    // Convert the Set back to an Array for n8n compatibility
    existingKeys: Array.from(uniqueKeysSet)
  }
}];

// 1. Retrieve the existing keys from the previous node
const existingKeysArray = $('Build Existing Keys').first().json.existingKeys;
const existingKeys = new Set(existingKeysArray);

// 2. Identify the node providing the NEW data
// IMPORTANT: Ensure 'Code in JavaScript2' is the correct name of the node with your emails
const incomingItems = $('Remove Duplicates').all(); 

const newItems = [];

for (const item of incomingItems) {
  // Extract values from the incoming node
  const email = (item.json['Email Address'] || item.json['email'] || '').toString().toLowerCase().trim();
  const name  = (item.json['producer_name'] || item.json['Prodcuer Name'] || '').toString().toLowerCase().trim();

  // Create a unique key to compare
  const key = `${email}||${name}`;

  if (!existingKeys.has(key) && key !== "||") {
    newItems.push({ 
      json: { 
        ...item.json, 
        "Email Address": email, // Explicitly ensure this field is passed forward
        "Prodcuer Name": name,  // Ensure consistent naming for your sheet
        _status: 'NEW' 
      } 
    });
    // Add to set to catch duplicates within the same run
    existingKeys.add(key);
  }
}

// 3. Return results
return newItems.length > 0 ? newItems : [{ json: { _status: 'NO_NEW_ITEMS' } }];

